<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue'
import {LayoutDashboard,FolderOpen,Mic2,Upload,Headphones,Plus,Search,Trash2,Pencil,Play,Pause,Rss,Download,AudioLines,Settings,LogOut,X,Music2,CheckCircle2,AlertCircle,Menu} from 'lucide-vue-next'
import {putAudio,getAudio,delAudio} from './storage'
const KEY='mecast-v1'
const blank=()=>({user:null,series:[{id:'demo',title:'Primeiros passos',description:'Série de demonstração do meCast.',category:'Educação',createdAt:new Date().toISOString()}],episodes:[]})
function load(){try{return JSON.parse(localStorage.getItem(KEY))||blank()}catch{return blank()}}
const db=ref(load()),page=ref('dashboard'),modal=ref(''),toast=ref(''),query=ref(''),filter=ref('all'),busy=ref(false),error=ref(''),sidebarOpen=ref(false)
const login=ref({name:'',email:''}),sf=ref({title:'',description:'',category:'Geral'}),ef=ref({title:'',description:'',seriesId:'',file:null}),editing=ref(null)
const player=ref(null),playing=ref(null),audioUrl=ref(''),now=ref(0),dur=ref(0)
watch(db,v=>localStorage.setItem(KEY,JSON.stringify(v)),{deep:true})
const episodes=computed(()=>[...db.value.episodes].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)))
const published=computed(()=>episodes.value.filter(e=>e.status==='published'))
const filtered=computed(()=>episodes.value.filter(e=>(filter.value==='all'||e.seriesId===filter.value)&&(`${e.title} ${e.description}`.toLowerCase().includes(query.value.toLowerCase()))))
const current=computed(()=>db.value.episodes.find(e=>e.id===playing.value))
const initials=computed(()=>db.value.user?.name?.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()||'MC')
function msg(t){toast.value=t;setTimeout(()=>toast.value='',2800)}
function uid(){return crypto.randomUUID?.()||String(Date.now()+Math.random())}
function date(d){return new Date(d).toLocaleDateString('pt-BR')}
function time(n){if(!Number.isFinite(n))return '0:00';return `${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`}
function size(n){return n<1024*1024?`${(n/1024).toFixed(0)} KB`:`${(n/1024/1024).toFixed(1)} MB`}
function sname(id){return db.value.series.find(s=>s.id===id)?.title||'Série removida'}
function nav(p){page.value=p}
function newSeries(){editing.value=null;sf.value={title:'',description:'',category:'Geral'};modal.value='series'}
function editSeries(s){editing.value=s.id;sf.value={title:s.title,description:s.description,category:s.category};modal.value='series'}
function saveSeries(){if(!sf.value.title.trim())return msg('Informe o nome da série.');if(editing.value){Object.assign(db.value.series.find(s=>s.id===editing.value),sf.value)}else db.value.series.push({id:uid(),...sf.value,createdAt:new Date().toISOString()});modal.value='';msg('Série salva.')}
async function removeSeries(s){if(!confirm(`Excluir "${s.title}" e seus episódios?`))return;for(const e of db.value.episodes.filter(x=>x.seriesId===s.id)){await delAudio(e.id);if(playing.value===e.id)stop()};db.value.episodes=db.value.episodes.filter(e=>e.seriesId!==s.id);db.value.series=db.value.series.filter(x=>x.id!==s.id);msg('Série removida.')}
function newEpisode(seriesId=''){editing.value=null;ef.value={title:'',description:'',seriesId:seriesId||db.value.series[0]?.id||'',file:null};error.value='';modal.value='episode'}
function fileChange(e){const f=e.target.files?.[0];ef.value.file=f||null;error.value=f&&!f.type.startsWith('audio/')?'Selecione um arquivo de áudio.':f&&f.size>100*1024*1024?'Limite de 100 MB excedido.':''}
async function duration(file){return new Promise(ok=>{const u=URL.createObjectURL(file),a=new Audio();a.onloadedmetadata=()=>{URL.revokeObjectURL(u);ok(Number.isFinite(a.duration)?a.duration:0)};a.onerror=()=>{URL.revokeObjectURL(u);ok(0)};a.src=u})}
async function saveEpisode(){if(!ef.value.title.trim()||!ef.value.seriesId)return error.value='Preencha o título e selecione uma série.';if(editing.value){const e=db.value.episodes.find(x=>x.id===editing.value);Object.assign(e,{title:ef.value.title,description:ef.value.description,seriesId:ef.value.seriesId});modal.value='';return msg('Episódio atualizado.')}const f=ef.value.file;if(!f)return error.value='Selecione um áudio.';if(!f.type.startsWith('audio/')||f.size>100*1024*1024)return error.value='Arquivo inválido ou maior que 100 MB.';busy.value=true;try{const id=uid();await putAudio(id,f);const d=await duration(f);db.value.episodes.unshift({id,title:ef.value.title.trim(),description:ef.value.description,seriesId:ef.value.seriesId,fileName:f.name,mime:f.type,size:f.size,duration:d,status:'published',createdAt:new Date().toISOString(),publishedAt:new Date().toISOString()});modal.value='';msg('Áudio salvo e episódio publicado neste navegador.')}catch(e){error.value='Falha ao salvar. Verifique o espaço disponível.'}finally{busy.value=false}}
function editEpisode(e){editing.value=e.id;ef.value={title:e.title,description:e.description,seriesId:e.seriesId,file:null};error.value='';modal.value='episode'}
async function removeEpisode(e){if(!confirm(`Excluir "${e.title}"?`))return;if(playing.value===e.id)stop();await delAudio(e.id);db.value.episodes=db.value.episodes.filter(x=>x.id!==e.id);msg('Episódio removido.')}
async function play(e){try{if(playing.value===e.id&&player.value){player.value.paused?player.value.play():player.value.pause();return}stop();const blob=await getAudio(e.id);if(!blob)return msg('Arquivo não encontrado neste navegador.');audioUrl.value=URL.createObjectURL(blob);playing.value=e.id;await new Promise(r=>setTimeout(r,0));await player.value?.play()}catch{msg('Não foi possível reproduzir o áudio.')}}
function stop(){player.value?.pause();if(audioUrl.value)URL.revokeObjectURL(audioUrl.value);audioUrl.value='';playing.value=null;now.value=0;dur.value=0}
function rss(s){const esc=x=>String(x||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');const items=db.value.episodes.filter(e=>e.seriesId===s.id&&e.status==='published').map(e=>`<item><title>${esc(e.title)}</title><description>${esc(e.description)}</description><guid>${e.id}</guid><pubDate>${new Date(e.publishedAt).toUTCString()}</pubDate><enclosure url="LOCAL:${esc(e.fileName)}" length="${e.size}" type="${esc(e.mime)}"/></item>`).join('');const xml=`<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>${esc(s.title)}</title><description>${esc(s.description)}</description><link>https://example.invalid</link>${items}</channel></rss>`;download(xml,`${s.title.replace(/[^a-z0-9]/gi,'-')}.xml`,'application/rss+xml');msg('RSS XML exportado. URLs de áudio ainda são locais.')}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}
function backup(){download(JSON.stringify(db.value,null,2),'mecast-backup.json','application/json');msg('Backup dos metadados exportado.')}
function signIn(){if(!login.value.name.trim()||!login.value.email.includes('@'))return msg('Informe nome e e-mail válidos.');db.value.user={...login.value};modal.value='';msg('Bem-vindo ao meCast!')}
function reset(){if(!confirm('Apagar séries, episódios e áudios locais?'))return;Promise.all(db.value.episodes.map(e=>delAudio(e.id))).then(()=>{db.value=blank();stop();msg('Dados apagados.')})}
onMounted(()=>{if(!db.value.user)modal.value='login'})
onBeforeUnmount(stop)
</script>
<template>
<div class="layout">
<aside class="side" :class="{show:sidebarOpen}"><div class="logo"><span class="mark"><AudioLines/></span>me<span>Cast</span></div><small class="caption">WORKSPACE</small>
<button :class="{active:page==='dashboard'}" @click="nav('dashboard')"><LayoutDashboard/> Visão geral</button>
<button :class="{active:page==='series'}" @click="nav('series')"><FolderOpen/> Minhas séries <i>{{db.series.length}}</i></button>
<button :class="{active:page==='episodes'}" @click="nav('episodes')"><Mic2/> Episódios <i>{{db.episodes.length}}</i></button>
<small class="caption gap">PUBLICAÇÃO</small><button @click="newEpisode()"><Upload/> Novo episódio</button><button :class="{active:page==='player'}" @click="nav('player')"><Headphones/> Player público</button>
<div class="side-bottom"><div class="local"><b>Modo local</b><p>Dados salvos neste navegador.</p><small>Sem servidor conectado</small></div><div class="user"><span class="avatar">{{initials}}</span><span><b>{{db.user?.name||'Usuário'}}</b><small>{{db.user?.email||'Conta local'}}</small></span><button title="Sair" @click="db.user=null;modal='login'"><LogOut/></button></div></div></aside>
<main><header><div class="crumb"><button class="hamb" @click="sidebarOpen=!sidebarOpen"><Menu/></button>Workspace <b>/</b> {{page==='dashboard'?'Visão geral':page==='series'?'Minhas séries':page==='episodes'?'Episódios':'Player público'}}</div><div class="head-actions"><div class="search"><Search/><input v-model="query" placeholder="Buscar episódios..." @keyup.enter="nav('episodes')"></div><span class="avatar">{{initials}}</span></div></header>
<div class="content">
<template v-if="page==='dashboard'">
<div class="heading"><div><small class="eyebrow">SEU ESTÚDIO DE PODCAST</small><h1>Olá, {{db.user?.name?.split(' ')[0]||'criador'}} <em>✦</em></h1><p>Acompanhe seu conteúdo e continue de onde parou.</p></div><button class="primary" @click="newEpisode()"><Plus/> Novo episódio</button></div>
<div class="stats"><article><label>Total de séries</label><strong>{{db.series.length}}</strong><small>Organizadas no seu estúdio</small></article><article><label>Episódios publicados</label><strong>{{published.length}}</strong><small>Disponíveis no catálogo local</small></article><article><label>Tempo de áudio</label><strong>{{Math.floor(db.episodes.reduce((n,e)=>n+e.duration,0)/3600)}}h {{Math.floor(db.episodes.reduce((n,e)=>n+e.duration,0)%3600/60)}}m</strong><small>Duração cadastrada</small></article><article><label>Armazenamento</label><strong>{{size(db.episodes.reduce((n,e)=>n+e.size,0))}}</strong><small>Arquivos neste navegador</small></article></div>
<div class="columns"><section class="panel"><div class="panel-head"><div><h2>Adicionados recentemente</h2><p>Seus últimos episódios</p></div><button class="link" @click="nav('episodes')">Ver todos ↗</button></div><div v-for="e in episodes.slice(0,5)" :key="e.id" class="episode"><button class="play" @click="play(e)"><Pause v-if="playing===e.id&&!player?.paused"/><Play v-else/></button><span class="art"><Music2/></span><span class="ep-title"><b>{{e.title}}</b><small>{{sname(e.seriesId)}} · {{date(e.createdAt)}}</small></span><span class="pill">Publicado</span><small>{{time(e.duration)}}</small></div><div v-if="!episodes.length" class="empty"><FileAudio/><b>Nenhum episódio ainda</b><p>Envie seu primeiro áudio para começar.</p><button class="primary" @click="newEpisode()">Adicionar episódio</button></div></section>
<section class="panel quick"><div class="panel-head"><div><h2>Acesso rápido</h2><p>Continue seu trabalho</p></div></div><button @click="newSeries()"><FolderOpen/><span><b>Criar uma série</b><small>Organize seus episódios</small></span>↗</button><button @click="newEpisode()"><Upload/><span><b>Enviar áudio</b><small>Adicione um episódio</small></span>↗</button><button @click="nav('player')"><Headphones/><span><b>Ver player</b><small>Confira a prévia pública</small></span>↗</button><div class="tip">Dica do estúdio<p>Organize seus episódios em séries para manter seu catálogo fácil de navegar.</p></div></section></div>
</template>
<template v-else-if="page==='series'">
<div class="heading"><div><small class="eyebrow">BIBLIOTECA</small><h1>Minhas séries</h1><p>Organize seus podcasts em coleções.</p></div><button class="primary" @click="newSeries()"><Plus/> Criar série</button></div>
<div class="series-grid"><article v-for="(s,i) in db.series" :key="s.id" class="series-card"><div class="cover" :class="'c'+i%4"><span>{{s.category}}</span><AudioLines/><button @click="editSeries(s)"><Pencil/></button></div><div class="series-body"><div class="line"><b>{{s.title}}</b><button class="plain" @click="removeSeries(s)"><Trash2/></button></div><p>{{s.description||'Sem descrição.'}}</p><small>{{db.episodes.filter(e=>e.seriesId===s.id).length}} episódios · {{date(s.createdAt)}}</small><div class="actions"><button class="secondary" @click="filter=s.id;nav('episodes')">Ver episódios</button><button class="secondary" @click="newEpisode(s.id)"><Plus/> Adicionar</button><button class="secondary icon" @click="rss(s)"><Rss/></button></div></div></article><button class="add-card" @click="newSeries()"><Plus/><b>Criar nova série</b><small>Comece uma coleção</small></button></div>
</template>
<template v-else-if="page==='episodes'">
<div class="heading"><div><small class="eyebrow">BIBLIOTECA</small><h1>Episódios</h1><p>Gerencie seus arquivos e publicações.</p></div><button class="primary" @click="newEpisode()"><Plus/> Novo episódio</button></div>
<div class="filters"><div class="search"><Search/><input v-model="query" placeholder="Buscar por título ou descrição"></div><select v-model="filter"><option value="all">Todas as séries</option><option v-for="s in db.series" :value="s.id">{{s.title}}</option></select></div>
<section class="panel table"><div class="table-head"><span>Episódio</span><span>Série</span><span>Data</span><span>Status</span><span>Duração</span><span></span></div><div v-for="e in filtered" :key="e.id" class="table-row"><div class="ep-title"><b>{{e.title}}</b><small>{{e.fileName}}</small></div><span>{{sname(e.seriesId)}}</span><span>{{date(e.createdAt)}}</span><span class="pill">Publicado</span><span>{{time(e.duration)}}</span><div class="row-actions"><button class="plain" @click="editEpisode(e)"><Pencil/></button><button class="plain" @click="removeEpisode(e)"><Trash2/></button></div></div><div v-if="!filtered.length" class="empty"><b>Nenhum episódio encontrado</b><p>Altere os filtros ou envie um áudio.</p></div></section>
</template>
<template v-else>
<div class="heading"><div><small class="eyebrow">EXPERIÊNCIA PÚBLICA</small><h1>Player do meCast</h1><p>Prévia local dos episódios publicados.</p></div><span class="preview">● PRÉVIA</span></div><section class="public"><div class="public-hero"><span class="mark"><AudioLines/></span><div><small class="eyebrow">SEU CATÁLOGO</small><h2>Ouça suas ideias.</h2><p>Seus episódios publicados em um só lugar.</p></div></div><div class="panel-head"><h2>Últimos episódios</h2><small>{{published.length}} publicados</small></div><div v-for="e in published" class="episode"><button class="play" @click="play(e)"><Pause v-if="playing===e.id&&!player?.paused"/><Play v-else/></button><span class="ep-title"><b>{{e.title}}</b><small>{{sname(e.seriesId)}} · {{date(e.createdAt)}}</small></span><small>{{time(e.duration)}}</small></div><div v-if="!published.length" class="empty">Nenhum episódio publicado.</div></section><div class="rss-list"><div v-for="s in db.series" class="rss-row"><Rss/><span><b>{{s.title}}</b><small>{{db.episodes.filter(e=>e.seriesId===s.id).length}} episódios no feed</small></span><button class="secondary" @click="rss(s)"><Download/> Exportar RSS</button></div></div>
</template>
</div>
<footer><span>© 2026 meCast</span><span>Dados armazenados localmente neste navegador</span><button @click="backup()"><Download/> Backup</button><button @click="reset()"><Settings/> Limpar dados</button></footer>
</main>
<div v-if="current&&audioUrl" class="dock"><div class="ep-title"><b>{{current.title}}</b><small>{{sname(current.seriesId)}}</small></div><button class="play" @click="player.paused?player.play():player.pause()"><Pause v-if="player&&!player.paused"/><Play v-else/></button><span>{{time(now)}}</span><input type="range" min="0" :max="dur||0" :value="now" @input="player.currentTime=+$event.target.value"><span>{{time(dur)}}</span><button class="plain" @click="stop()"><X/></button><audio ref="player" :src="audioUrl" @timeupdate="now=player.currentTime;dur=player.duration||0" @loadedmetadata="dur=player.duration||0" @ended="stop()"/></div>
</div>
<div v-if="modal" class="overlay" @click.self="modal=''"><section class="modal">
<template v-if="modal==='login'"><div class="logo"><span class="mark"><AudioLines/></span>me<span>Cast</span></div><small class="eyebrow">SEU ESTÚDIO DE PODCAST</small><h2>Boas-vindas.</h2><p>Entre no seu espaço de criação.</p><form @submit.prevent="signIn"><label>Seu nome<input v-model="login.name" required placeholder="Como podemos te chamar?"></label><label>E-mail<input v-model="login.email" type="email" required placeholder="voce@exemplo.com"></label><button class="primary">Entrar no meCast</button></form><small class="disclaimer">Acesso demonstrativo; não há autenticação em servidor.</small></template>
<template v-else><div class="modal-head"><div><small class="eyebrow">{{modal==='series'?'BIBLIOTECA':'CONTEÚDO'}}</small><h2>{{modal==='series'?(editing?'Editar série':'Criar série'):(editing?'Editar episódio':'Novo episódio')}}</h2></div><button class="plain" @click="modal=''"><X/></button></div>
<form v-if="modal==='series'" @submit.prevent="saveSeries"><label>Nome da série<input v-model="sf.title" required placeholder="Ex.: Conversas sobre tecnologia"></label><label>Descrição<textarea v-model="sf.description" rows="3"></textarea></label><label>Categoria<select v-model="sf.category"><option>Geral</option><option>Educação</option><option>Tecnologia</option><option>Cultura</option><option>Negócios</option><option>Entretenimento</option></select></label><div class="modal-actions"><button type="button" class="secondary" @click="modal=''">Cancelar</button><button class="primary">Salvar série</button></div></form>
<form v-else @submit.prevent="saveEpisode"><label>Título do episódio<input v-model="ef.title" required></label><label>Descrição<textarea v-model="ef.description" rows="3"></textarea></label><label>Série<select v-model="ef.seriesId" required><option disabled value="">Selecione uma série</option><option v-for="s in db.series" :value="s.id">{{s.title}}</option></select></label><label v-if="!editing" class="drop"><input type="file" accept="audio/*,.mp3,.wav,.ogg,.m4a,.aac" @change="fileChange"><Upload/><b>{{ef.file?.name||'Selecionar arquivo de áudio'}}</b><small>{{ef.file?size(ef.file.size):'MP3, WAV, OGG, M4A · Máximo 100 MB'}}</small></label><p class="hint"><AlertCircle/> Arquivo salvo neste navegador. Sem transcodificação FFmpeg nesta versão.</p><p v-if="error" class="error">{{error}}</p><div class="modal-actions"><button type="button" class="secondary" @click="modal=''">Cancelar</button><button class="primary" :disabled="busy">{{busy?'Salvando...':editing?'Salvar alterações':'Publicar episódio'}}</button></div></form></template>
</section></div><Transition><div v-if="toast" class="toast"><CheckCircle2/> {{toast}}</div></Transition>
</template>
